const screenshotViews = {
  incidents: {
    file: "sentinel-incidents.png",
    alt: "Microsoft Sentinel showing two open medium severity brute force logon detection incidents",
    caption:
      "Two medium severity incidents generated by the brute force logon detection rule.",
    width: 1304,
    height: 868,
  },
  query: {
    file: "sentinel-query.png",
    alt: "KQL query filtering SecurityEvent for Event ID 4625 and sorting by TimeGenerated",
    caption: "The KQL query I used to review failed authentication events.",
    width: 1610,
    height: 406,
  },
  logins: {
    file: "failed-logons.png",
    alt: "Microsoft Sentinel query results showing repeated Windows Security Event ID 4625 failed login records",
    caption:
      "Failed authentication records visible in the lab on May 22, 2025.",
    width: 1905,
    height: 906,
  },
};
const screenshotImage = document.querySelector("#showcase-image");
if (screenshotImage) {
  document.querySelectorAll("[data-evidence]").forEach((button) =>
    button.addEventListener("click", () => {
      const view = screenshotViews[button.dataset.evidence];
      screenshotImage.src = "../assets/evidence/sentinel/" + view.file;
      screenshotImage.alt = view.alt;
      screenshotImage.width = view.width;
      screenshotImage.height = view.height;
      document.querySelector("#showcase-image-link").href = screenshotImage.src;
      document.querySelector("#showcase-caption").textContent = view.caption;
      document
        .querySelectorAll("[data-evidence]")
        .forEach((item) =>
          item.setAttribute("aria-pressed", String(item === button)),
        );
    }),
  );
}
